callGraph.callee:
[...nodeIds]
    .map((id) => {
      const kn = nodePool[id];
      if (!kn) return null;
      const dims = kn.dimensions ?? [];
      const role = kn.role ?? 'plain';
      return {
        id,
        label: kn.label,
        role,
        isFocus: focus === id,
        dimmed: isDimmed(dims, dimension),
        zone:
          role === 'axiom' || role === 'mechanism' || role === 'conclusion'
            ? role
            : undefined,
      } satisfies ViewNode;
    })
    .filter

params:
{
  x, y, nodeId, hasChildren, onClose,
  onAdd, onRename, onDelete, onAddQuestion,
}
